    expect(validateSettings({ wsCompressPaths: [42] })?.key).toBe("wsCompressPaths");
  });

  it("空数组合法", () => {
    expect(validateSettings({ wsCompressPaths: [] })).toBe(null);
  });

  // undefined/null 字段跳过
  it("undefined/null 字段跳过校验", () => {
    expect(validateSettings({ port: undefined, host: null })).toBe(null);
  });
});

